var memberCounters={};
// Exact loop visits for the registered implementations; these units are member-specific.
function predictState(state,a,b,meter={}){
  const s=state,chars=a.length+b.length;
  if(s.kind==='constant')return s.value;
  if(s.kind==='count'){
    meter.characterVisits=chars*s.alphabet.length;
    const feature=w=>{const c=counts(w,s.alphabet);return s.basis.map(({p,weights})=>c.reduce((n,x,i)=>n+x*weights[i],0)%p);};
    return JSON.stringify(feature(a))===JSON.stringify(feature(b));
  }
  if(s.kind==='fold'){meter.characterVisits=chars;return fold(a,s.spec)===fold(b,s.spec);}
  if(s.kind==='joint'){
    meter.characterVisits=chars*(s.alphabet.length+1);
    const n=new Map(s.table).get(jointKey({a,b},s.spec,s.alphabet,s.quotients));return n?n[1]>n[0]:false;
  }
  if(s.kind==='finite-state'){
    meter.characterVisits=chars;meter.pointTransitions=chars*s.points;
    const run=w=>{let state=Array.from({length:s.points},(_,i)=>i);for(const c of w)state=state.map(x=>Math.floor(s.images[c]/s.points**x)%s.points);return state.join(',');};return run(a)===run(b);
  }
  if(s.kind==='bfs'){const r=rewriteSearch(a,b,s.rules,s.budget,{bidirectional:s.bidirectional});Object.assign(meter,r);delete meter.prediction;return r.prediction;}
  if(s.kind==='canonical'){meter.positionLimit=2*s.maxPositions;return canonicalModel(s,{maxSteps:s.maxSteps,maxPositions:s.maxPositions}).predict(a,b);}
  if(s.kind==='nuisance'){
    meter.dpCells=a.length*b.length;meter.characterVisits=chars*s.alphabet.length+a.length;
    meter.bigramPositions=(Math.max(0,a.length-1)+Math.max(0,b.length-1))*s.alphabet.length**2;
    return (nuisanceVector({a,b},s)[s.stump.index]<=s.stump.threshold)===s.stump.direction;
  }
  throw new Error('unknown serialized reference model');
}

const SEARCH_CURVES=Object.freeze([{name:'b2',maxNodes:128,maxPositions:4096,lengthSlack:6},{name:'4x',maxNodes:512,maxPositions:16384,lengthSlack:6},{name:'16x',maxNodes:2048,maxPositions:65536,lengthSlack:6}]);
function rewriteSearch(a,b,rules,budget,{bidirectional=false}={}){
  const stats={visitedNodes:1,testedPositions:0,maxDepth:0,budgetExhausted:false};
  if(a===b)return {prediction:true,...stats};
  const edges=rules.flatMap(r=>[[r.u,r.v],[r.v,r.u]]),queues=[[{s:a,depth:0}],[{s:b,depth:0}]],seen=[new Set([a]),new Set([b])],heads=[0,0],maxLength=Math.max(a.length,b.length)+budget.lengthSlack;
  if(bidirectional)stats.visitedNodes=2;
  for(;;){
    const side=bidirectional?(queues[0].length-heads[0]<=queues[1].length-heads[1]?0:1):0;
    if(heads[side]>=queues[side].length)return {prediction:false,...stats};
    const {s,depth}=queues[side][heads[side]++];stats.maxDepth=Math.max(stats.maxDepth,depth);
    for(const [from,to]of edges)for(let position=0;position<=s.length-from.length;position++){
      if(stats.testedPositions>=budget.maxPositions)return {prediction:false,...stats,budgetExhausted:true};stats.testedPositions++;
      if(s.slice(position,position+from.length)!==from)continue;
      const next=s.slice(0,position)+to+s.slice(position+from.length);
      if(next.length>maxLength)continue;
      if((bidirectional?seen[1-side].has(next):next===b))return {prediction:true,...stats,maxDepth:Math.max(stats.maxDepth,depth+1)};
      if(seen[side].has(next))continue;
      if(stats.visitedNodes>=budget.maxNodes)return {prediction:false,...stats,budgetExhausted:true};
      seen[side].add(next);queues[side].push({s:next,depth:depth+1});stats.visitedNodes++;
    }
  }
}
function canonicalModel(view,{maxSteps=128,maxPositions=16384}={}){
  const rules=view.rules.map(({u,v})=>u.length>v.length||u.length===v.length&&u>v?[u,v]:[v,u]);
  const normalize=word=>{let used=0;for(let step=0;step<maxSteps;step++){let changed=false;for(const [from,to]of rules){for(let i=0;i<=word.length-from.length;i++){if(++used>maxPositions)return word;if(word.slice(i,i+from.length)===from){word=word.slice(0,i)+to+word.slice(i+from.length);changed=true;break;}}if(changed)break;}if(!changed)break;}return word;};
  return {state:{kind:'canonical',rules:view.rules,maxSteps,maxPositions},predict:(a,b)=>normalize(a)===normalize(b)};
}

function predict(serialized,a,b){memberCounters={};return predictState(JSON.parse(serialized).state,a,b,memberCounters);}
